const wrong = {
  setup: ["Use the previous person's settings and let the first loaded repetition determine whether the {exercise} position happens to fit", "Start the {exercise} from a deliberately unstable stance so the client has to discover balance while controlling the full resistance", "Choose hand, foot, and equipment positions solely by copying the trainer, without accounting for the client's proportions or available range"],
  move: ["Accelerate every phase of the {exercise} with momentum, change direction by rebounding, and correct the path only after the set", "Move the resistance through a different path on each repetition so no single joint or muscle receives consistent loading", "Relax at the transition of the {exercise}, allow the load to reverse direction uncontrolled, and then regain tension near the finish"],
  align: ["Permit the working joints to drift toward whichever position moves the greatest load, even when balance and tracking change between repetitions", "Shift repeatedly toward the client's stronger side during the {exercise}, because asymmetrical loading is expected whenever fatigue begins", "Prioritize completing the prescribed repetitions over maintaining the client's base of support, joint tracking, and controlled spinal position"],
  observe: ["Stand directly in the {exercise} implement's travel path and focus on a single joint while the rest of the client is obscured", "Remain at the far end of the room, count repetitions, and wait until the client asks whether any technique changes occurred", "Use one obstructed viewing angle for the entire {exercise}, even when it hides the joints and contact points most relevant to safety"],
  error: ["The client uses controlled breathing while keeping the prescribed contact points stable through the full set", "The client maintains a consistent pain-free range that matches the available mobility and equipment setup", "The client uses a smooth repeatable tempo without unwanted momentum while preserving balance and joint tracking"],
  fix: ["Increase both resistance and speed so the additional momentum carries the client through the faulty portion of the {exercise}", "Let the client repeat the same fault until the planned set ends, then provide every relevant correction simultaneously during the rest period", "Hold the client or implement in the desired path and manually force the remaining {exercise} repetitions through the unavailable range"],
  breathe: ["Hold the breath continuously from the first {exercise} repetition until the complete set has ended, regardless of load or health status", "Use rapid shallow breaths only while passing the sticking point and avoid establishing a repeatable breathing rhythm during the easier phase", "Exhale throughout the lowering phase of every {exercise} repetition and avoid inhaling until the resistance returns to its start position"],
  trainer: ["Stand inside the {exercise} load path, maintain contact with the implement on every repetition, and provide assistance before the client needs it", "Observe the {exercise} from across the room and approach only after the client has already lost control of the resistance or balance", "Use whichever contact point makes the {exercise} feel lighter, even if it cannot control the implement or places the trainer near moving equipment"],
};

for (const [topic, setup, movement, alignment, observation, error, correction, breathing, trainer] of profiles) {
  const exercise = topic.replace(/ technique$/, "");
  const alternatives = (kind) => wrong[kind].map((option) => option.replaceAll("{exercise}", exercise));
  add({ topic, question: `Which setup is most appropriate for the ${exercise}?`, correct: setup, wrong: alternatives("setup"), explanation: `A sound ${exercise} begins with this stable, individualized setup. The client should not load the movement until the trainer has checked the relevant contacts, implement position, and clearance.` });
  add({ topic, question: `Which description best captures the intended execution of the ${exercise}?`, correct: movement, wrong: alternatives("move"), explanation: `This sequence preserves the ${exercise}'s intended joint actions and keeps the resistance controlled through both phases. A repeatable ${exercise} path also lets the trainer distinguish purposeful movement from fatigue-related compensation.` });
  add({ topic, question: `Which alignment standard should the trainer reinforce during the ${exercise}?`, correct: alignment, wrong: alternatives("align"), explanation: `This alignment keeps the ${exercise} balanced and limits avoidable compensation. The client's ${exercise} range may vary, but control should not be traded for load.` });
  add({ topic, type: "scenario", question: `A client is learning the ${exercise}. How should the trainer position themself to evaluate technique?`, correct: observation, wrong: alternatives("observe"), explanation: `The trainer needs a useful view of the ${exercise} while respecting the implement path and the client's balance. The observation position may change between ${exercise} repetitions when it is safe.` });
  add({ topic, question: `Which is a meaningful technique fault during the ${exercise}?`, correct: error, wrong: alternatives("error"), explanation: `This ${exercise} fault indicates that load, range, coordination, mobility, or fatigue is exceeding what the client can presently control. The trainer should intervene before the ${exercise} compensation becomes the client's repeated strategy.` });
  add({ topic, type: "scenario", question: `The trainer observes ${error} during the ${exercise}. What is the best initial correction?`, correct: correction, wrong: alternatives("fix"), explanation: `This correction reduces the ${exercise} to a level where the client can practice the intended pattern. If a concise cue does not restore ${exercise} control, the set should end or the movement should be regressed.` });
  add({ topic, question: `What breathing pattern is generally appropriate for the ${exercise}?`, correct: breathing, wrong: alternatives("breathe"), explanation: `The ${exercise} generally follows the NSCA pattern of inhaling during the easier eccentric portion and exhaling through exertion. A brief Valsalva is relevant only when the ${exercise} is a heavy structural lift and the lifter is appropriately screened and technique-experienced.` });
  add({ topic, type: "scenario", question: `A client is preparing for a working set of the ${exercise}, and the trainer has confirmed the planned repetitions and stop signal. What is the trainer's safest spotting or supervision strategy?`, correct: trainer, wrong: alternatives("trainer"), explanation: `Spotting the ${exercise} must match its implement, speed, and risk. The trainer should use a mechanically safe position and provide no more ${exercise} assistance than necessary unless immediate danger requires decisive action.` });
}

const expected = 343;
if (questions.length !== expected) throw new Error(`Expected ${expected} questions, built ${questions.length}`);
await writeFile(join(root, "data/exercise-technique.json"), `${JSON.stringify(questions, null, 2)}\n`);
console.log(`Wrote ${questions.length} exercise-technique questions.`);
